//! Differential test of name resolution against IA's Jython compiler.
//!
//! `tests/oracle/scope.cases` holds programs generated by
//! `oracle/scope/generate.py` (a stratified sample, see
//! `oracle/scope/run.sh`) and hand-written ones; `scope.expected` is what
//! Jython's code generator does with every name of each (recorded with
//! `oracle/scope/run.sh`): per code object, which frame accessor each read,
//! store and delete compiles to, with the mangled spelling, and every
//! attribute name. [`scope_dump`] must produce the same from the semantic
//! model, and the model must report a compile error exactly where Jython
//! does not compile.

use iglint_python_semantic::{SemanticModel, SemanticOptions, compile_errors, scope_dump};

fn records(text: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    let mut name: Option<String> = None;
    let mut body = String::new();
    for line in text.split_inclusive('\n') {
        if let Some(n) = line.strip_prefix("### ") {
            if let Some(prev) = name.take() {
                out.push((prev, std::mem::take(&mut body)));
            }
            name = Some(n.trim_end().to_owned());
        } else {
            body.push_str(line);
        }
    }
    if let Some(n) = name {
        out.push((n, body));
    }
    out
}

/// Compares every case; returns the number checked and the failures.
fn compare(cases: &str, expected: &str) -> (usize, Vec<String>) {
    let sources = records(cases);
    let expected = records(expected);
    assert_eq!(
        sources.len(),
        expected.len(),
        "cases and expectations differ"
    );
    let mut failures = Vec::new();
    for ((name, source), (expected_name, outcome)) in sources.iter().zip(&expected) {
        assert_eq!(name, expected_name);
        let parsed = iglint_python::parse_module(source);
        let jython_ok = outcome.starts_with("ok\n");
        let model = SemanticModel::build(&parsed.module, &SemanticOptions::default());
        let errors = if parsed.errors.is_empty() {
            compile_errors(&model).len()
        } else {
            parsed.errors.len()
        };
        if !jython_ok {
            if errors == 0 {
                failures.push(format!(
                    "{name}: Jython does not compile it ({}), we report nothing",
                    outcome.lines().nth(1).unwrap_or("")
                ));
            }
            continue;
        }
        if errors != 0 {
            failures.push(format!("{name}: Jython compiles it, we report errors"));
            continue;
        }
        let ours = scope_dump(&model, source);
        let theirs = &outcome["ok\n".len()..];
        if ours != theirs {
            failures.push(format!(
                "{name}:\n{source}--- jython\n{}--- iglint\n{}",
                diff_lines(theirs, &ours).0,
                diff_lines(theirs, &ours).1
            ));
        }
    }
    (sources.len(), failures)
}

/// The lines only in `a` and only in `b` (with their scope headers).
fn diff_lines(a: &str, b: &str) -> (String, String) {
    let only = |x: &str, y: &str| {
        let keyed = |text: &str| {
            let mut scope = String::new();
            let mut out = Vec::new();
            for line in text.lines() {
                if line.starts_with("scope ") {
                    scope = line.to_owned();
                }
                out.push(format!("{scope} | {line}"));
            }
            out
        };
        let ys: std::collections::HashSet<String> = keyed(y).into_iter().collect();
        let mut out = String::new();
        for line in keyed(x) {
            if !ys.contains(&line) {
                out.push_str(&line);
                out.push('\n');
            }
        }
        out
    };
    (only(a, b), only(b, a))
}

#[test]
fn name_access_matches_jython() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/oracle");
    let cases = std::fs::read_to_string(format!("{dir}/scope.cases")).unwrap();
    let expected = std::fs::read_to_string(format!("{dir}/scope.expected")).unwrap();
    let (checked, failures) = compare(&cases, &expected);
    eprintln!("{checked} scope oracle cases");
    assert!(checked > 500, "only {checked} cases");
    assert!(
        failures.is_empty(),
        "{} differences:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

/// The full run: `oracle/scope/run.sh random` sets the paths.
#[test]
#[ignore]
fn name_access_matches_jython_random_run() {
    let cases = std::env::var("IGLINT_SCOPE_CASES").expect("IGLINT_SCOPE_CASES");
    let expected = std::env::var("IGLINT_SCOPE_EXPECTED").expect("IGLINT_SCOPE_EXPECTED");
    let cases = std::fs::read_to_string(cases).unwrap();
    let expected = std::fs::read_to_string(expected).unwrap();
    let (checked, failures) = compare(&cases, &expected);
    eprintln!("{checked} cases, {} differences", failures.len());
    for f in failures.iter().take(20) {
        eprintln!("{f}");
    }
    assert!(failures.is_empty(), "{} differences", failures.len());
}
